import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/qr_g7_keks.B6q4c7CX.js";import{_ as s}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as a,o as n,c as r,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const w=JSON.parse('{"title":"G7, ONE+","description":"","frontmatter":{},"headers":[],"relativePath":"install/g7.md","filePath":"install/g7.md"}'),p={name:"install/g7.md"};function d(c,i,m,h,u,g){return n(),r("div",null,[...i[0]||(i[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Dex</p></div><h3 id="g7-or-one" tabindex="-1">G7 or ONE+ <a class="header-anchor" href="#g7-or-one" aria-label="Permalink to &quot;G7 or ONE+&quot;">​</a></h3><p>This describes how to connect a Dexcom G7 or ONE+ sensor directly to xDrip. Sensor and transmitter are a single disposable unit, and from xDrip&#39;s perspective G7 and ONE+ are the same device — every step below applies equally to both.</p><p>For G6 or Dexcom ONE, see the <a href="./g6.html">separate G6, Dexcom ONE page</a> instead.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Some of this also applies to Stelo when connected directly to xDrip — check the <a href="./datasource.html">data source guide</a> for current Stelo support.</p></div><h4 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h4><ul><li>Check your phone setup matches xDrip <a href="./prerequisites.html">prerequisites</a> (time sync, battery optimization).</li><li>Make sure xDrip is updated to at least the 2026.05.06 release.</li><li>Only one app can collect from the sensor: uninstall the Dexcom app if xDrip is to be the collector. If you need to keep the Dexcom app, only it can collect — use xDrip as a <a href="./companion.html">Companion app</a> follower instead. The same applies to the BYOD G7 app, which cannot broadcast to xDrip directly.</li></ul><div class="info custom-block"><p class="custom-block-title">t:slim / receiver order matters</p><p>Connect with xDrip <strong>first</strong>. If a pump or receiver connects to the sensor before xDrip, xDrip will not be able to connect to it — if one is already running, disable it and wait 15 minutes.</p></div><div class="warning custom-block"><p class="custom-block-title">Don&#39;t pair from Android Bluetooth settings</p><p>Never pair the sensor from the Android Bluetooth settings page — let xDrip trigger the pairing request, and approve it when asked.</p></div><h4 id="setup-xdrip" tabindex="-1">Set up xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Set up xDrip {#setup-xdrip}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Dex</p></div><p>Then scan this QR code with Settings → <a href="./../use/copysettings.html#auto-configure">Auto Configure</a> and approve the import prompt. It loads the G7 support data xDrip needs, which cannot be entered manually. This is a one-time setup — no need to repeat it for each new sensor.</p><p>QR Code - Click image to expand</p><p><a href="./images/qr_g7_keks.png"><img src="'+o+'" style="zoom:50%;"></a></p><p>Then verify the settings below — most match xDrip defaults, so this is a check rather than a reconfiguration. What each setting does is described in the <a href="./g6.html#dexcom-advanced-settings-reference">Dexcom advanced settings reference</a>, <a href="./../use/bluetooth.html">Bluetooth Settings</a> and <a href="./../use/misc.html">Other misc. options</a> pages.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Dex Debug Settings</p></div><div class="admonition xdripitem"><p class="admonition-title">Native Algorithm <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Use the transmitter&#39;s internal algorithm to calculate glucose values when possible.</p></div><div class="admonition xdripitem"><p class="admonition-title">Restart Sensor <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Automatically restart a sensor when it stops</p></div><div class="admonition xdripitem"><p class="admonition-title">Preemptive restarts <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Preemptively restart a sensor before the session ends on day 6/9 to avoid the warm-up time</p></div><p>A G7 session can never be restarted, so both restart options must stay disabled.</p><div class="admonition xdripitem"><p class="admonition-title">Go on without calibrations <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Keep using data even if there are not enough good calibrations (Experimental!)</p></div><div class="admonition xdripitem"><p class="admonition-title">Minimize Scanning <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use heuristics to minimize Bluetooth scanning + save power</p></div><div class="admonition xdripitem"><p class="admonition-title">Avoid Scanning <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Avoid scanning as much as possible (reduces battery usage further)</p></div><div class="info custom-block"><p class="custom-block-title">Scanning options</p><p>Minimize Scanning and Avoid Scanning save battery but are disastrous on some phones (Samsung, Chinese brands, ...). Start with both disabled — only try enabling them, one at a time, once your connection is reliable.</p></div><div class="admonition xdripitem"><p class="admonition-title">Allow OB1 unbonding <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> OB1 collector can unbond if it thinks the encryption has failed. If you get problems with it unpairing then disable this option. If you then totally lose connection, make sure this is enabled.</p></div><div class="admonition xdripitem"><p class="admonition-title">Special Pairing Workaround <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Some Samsung devices can have an error where they lose the pairing information. This attempts to work around the issue.</p></div><p>Enable Special Pairing Workaround on Samsung and some Chinese phones.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../use/misc.html">Other misc. options</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Engineering mode <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Allows changing the most unsafe settings which could break everything!</p></div><div class="admonition xdripitem"><p class="admonition-title">Battery Optimization prompt <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> On Android 6+ ensure battery optimization is switched off (recommended)</p></div><div class="admonition xdripitem"><p class="admonition-title">Wake Workarounds <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Use workarounds to avoid non-standard Android behavior of some handsets. Without this, collectors usually fail to get data.</p></div><div class="admonition xdripitem"><p class="admonition-title">Use Excessive Wakelocks <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Older gratuitous wakelocks which can drain extra battery but might be needed for Nightwatch or Android Wear.</p></div><div class="admonition xdripitem"><p class="admonition-title">Display Predictive Values <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Old method - Not recommended!</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Aggressive service restarts <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Repeatedly restart the collection service at any hint of missing data. Enable only if you are getting data loss.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../calibrate/advancedcal.html">Advanced Calibration</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Automatic Calibration <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Calibrate using new blood glucose readings if the conditions appear right to do so without asking confirmation (experimental)</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  <a href="./../use/lesscommon.html">Less common settings</a><br>   <a href="./../use/bluetooth.html">Bluetooth Settings</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Turn Bluetooth on <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Automatically enable Bluetooth if it is switched off when we try to connect to a Bluetooth device</p></div><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Watchdog <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Reset Bluetooth by turning it off and on if we don&#39;t get anything in 20 minutes</p></div><div class="admonition xdripitem"><p class="admonition-title">Close GATT on BLE disconnect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> If the Bluetooth watchdog activates often then you can try unchecking this option to see if it helps</p></div><div class="admonition xdripitem"><p class="admonition-title">Use scanning <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Scan before connecting on xBridge and Libre Bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><div class="admonition xdripitem"><p class="admonition-title">Trust Auto-Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use and trust Android Bluetooth auto connect feature</p></div><p>Start with Trust Auto-Connect disabled. Try enabling it only if you keep losing the connection.</p><div class="admonition xdripitem"><p class="admonition-title">Use Background Scans <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Use Android 8+ background scanning feature</p></div><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Older Bluetooth wakelocks which can drain extra battery but might be needed for Bluetooth reception</p></div><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Polling Mode <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Experimental support for xBridge+ polling feature</p></div><h4 id="starting-the-sensor" tabindex="-1">Starting the sensor <a class="header-anchor" href="#starting-the-sensor" aria-label="Permalink to &quot;Starting the sensor&quot;">​</a></h4><p>Insert the sensor following the manufacturer&#39;s applicator instructions. The session starts by itself the moment the sensor is inserted — there is nothing to start (or stop) in xDrip.</p><p>Take note of the 4-digit pairing code shown on the applicator; you&#39;ll need it next. If you&#39;re wearing two sensors during a changeover, mark the old one with a pen so you don&#39;t peel off the wrong one later.</p><h4 id="connecting-xdrip-to-the-sensor" tabindex="-1">Connecting xDrip to the sensor <a class="header-anchor" href="#connecting-xdrip-to-the-sensor" aria-label="Permalink to &quot;Connecting xDrip to the sensor&quot;">​</a></h4><ol><li>In Android Settings → Connected devices, forget any devices named <code>DXCM**</code>, <code>DX01**</code>, <code>DX02**</code> or <code>DX04**</code> (where <code>**</code> is any two characters), if listed.</li><li>Keep previously used sensors 10+ metres away or shielded (a metal box works).</li><li>Enter the 4-digit pairing code from the applicator:</li></ol><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Dexcom Transmitter ID</p></div><p>Watch the <a href="./../troubleshoot/systemstatus.html">Dex Status page</a> and approve the pairing request when it appears. If the sensor was inserted more than 30 minutes ago you should see readings right away; if just inserted, it shows as warming up and the status page fills in over time. Once battery voltages appear, it&#39;s safe to re-enable your pump or receiver.</p><h4 id="grace-period" tabindex="-1">Grace period <a class="header-anchor" href="#grace-period" aria-label="Permalink to &quot;Grace period&quot;">​</a></h4><p>A G7/ONE+ runs 10 days plus a 12-hour grace period — 10.5 days total. Use the extra 12 hours as a changeover buffer, or to overlap sensors (presoak): a new G7&#39;s first hours are its least stable, so inserting the next sensor before the old one ends gives smoother readings at switchover.</p><h4 id="starting-a-subsequent-sensor" tabindex="-1">Starting a subsequent sensor <a class="header-anchor" href="#starting-a-subsequent-sensor" aria-label="Permalink to &quot;Starting a subsequent sensor&quot;">​</a></h4><p>Switching to a new sensor is only a code change:</p><ol><li>Insert the new sensor around day 10 of the old one (see <a href="#starting-the-sensor">Starting the sensor</a>).</li><li>When ready to switch, enter the new sensor&#39;s 4-digit pairing code as the <a href="#connecting-xdrip-to-the-sensor">transmitter ID</a> and approve the new pairing request.</li></ol><p>Two useful tips:</p><ul><li>If the old sensor still shows as a <code>DXCM**</code> device in your Android Bluetooth history, forget it there.</li><li>Disable collection in xDrip <em>before</em> peeling off the old sensor — otherwise it may record one last, very low reading as the sensor leaves your skin.</li></ul><div class="info custom-block"><p class="custom-block-title">Pump or receiver users</p><p>Disable the pump/receiver connection first, let xDrip connect to the new sensor, and re-enable the pump once readings are stable. If the sensor won&#39;t connect, wait 15 minutes for <a href="./../troubleshoot/g7.html#g7-rapid-reconnect-mode">rapid reconnect mode</a> to kick in.</p></div><h4 id="unknown-firmware" tabindex="-1">Unknown firmware <a class="header-anchor" href="#unknown-firmware" aria-label="Permalink to &quot;Unknown firmware&quot;">​</a></h4><p>If the firmware version on the <a href="./../troubleshoot/systemstatus.html">System Status</a> page is flagged as unknown, you&#39;re most likely running an outdated xDrip — update to the latest release first. If the newest release still flags it, please report it in the <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">GitHub discussions</a>.</p><h4 id="problems" tabindex="-1">Problems? <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Problems?&quot;">​</a></h4><p>Try the <a href="./../troubleshoot/g7.html">G7, ONE+ troubleshooting</a> page.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',70)])])}const k=a(p,[["render",d]]);export{w as __pageData,k as default};
